import React from 'react';

const NoticeBar = () => {
  // EDIT THE TEXT BELOW TO CHANGE THE NOTICE CONTENT
  const noticeContent = {
    title: "IMPORTANT NOTICE",
    message: "Infinity Laghubitta Bittiya Sanstha Limited announces new interest rates effective from today. Please check our official circulars for details.",
    link: "/notices", // Change this to your notice page URL
    date: "2026-04-09"
  };

  const styles = {
    container: {
      background: '#fff3cd', // Light warning yellow
      borderBottom: '2px solid #ffeeba',
      padding: '10px 20px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      gap: '15px',
      zIndex: 1000,
      fontFamily: 'Arial, sans-serif'
    },
    badge: {
      background: '#d9534f', // Red badge
      color: 'white',
      padding: '4px 10px',
      borderRadius: '4px',
      fontSize: '0.8rem',
      fontWeight: 'bold',
      whiteSpace: 'nowrap'
    },
    text: {
      color: '#856404',
      fontSize: '0.95rem',
      margin: 0,
      fontWeight: '500'
    },
    link: {
      color: '#13a89e',
      textDecoration: 'underline',
      fontWeight: 'bold',
      fontSize: '0.9rem',
      cursor: 'pointer'
    }
  };

  return (
    <div style={styles.container}>
      <span style={styles.badge}>{noticeContent.title}</span>
      <p style={styles.text}>
        {noticeContent.message} 
        <a href={noticeContent.link} style={styles.link}> Read More</a>
      </p>
    </div>
  );
};

export default NoticeBar;
